-- Ssenari: Müştərinin zərər tarixcəsi (claims) əsasında sığorta haqqının hesablanması
-- Müştəri İD: 501, Baza KASKO haqqı: 1000 AZN

DECLARE @TargetCustomerId INT = 501;
DECLARE @BasePremium DECIMAL(10, 2) = 1000.00;
DECLARE @TotalPastClaims INT = 0;
DECLARE @FinalPremium DECIMAL(10, 2);
DECLARE @StatusMessage NVARCHAR(100);

-- 1. Müştərinin keçmiş təsdiqlənmiş qəza sayını bazadan sayırıq
SELECT @TotalPastClaims = COUNT(*)
FROM [dbo].[InsuranceClaims]
WHERE [CustomerID] = @TargetCustomerId
  AND [ClaimStatus] = N'APPROVED';

-- 2. IF...ELSE məntiqi ilə bonus-malus dərəcəsinin təyini
IF @TotalPastClaims = 0
BEGIN
    -- Müştərinin heç bir qəzası olmayıb: 20% bonus endirimi!
    SET @FinalPremium = @BasePremium * 0.80;
    SET @StatusMessage = N'Təhlükəsiz sürücü: 20% endirim tətbiq edildi.';
END
ELSE IF @TotalPastClaims BETWEEN 1 AND 2
BEGIN
    -- 1 və ya 2 qəza: Standart baza tarifi
    SET @FinalPremium = @BasePremium;
    SET @StatusMessage = N'Standart tarif tətbiq edildi.';
END
ELSE
BEGIN
    -- 3 və daha çox qəza: Yüksək risk cəriməsi (+40% artım)
    SET @FinalPremium = @BasePremium * 1.40;
    SET @StatusMessage = N'Yüksək riskli sürücü: +40% əlavə haqq hesablandı.';
END

-- 3. Yekun hesabatı təqdim edirik
SELECT 
    @TargetCustomerId AS [CustomerID],
    @TotalPastClaims AS [PastClaimsCount],
    @BasePremium AS [BasePremiumAZN],
    @FinalPremium AS [FinalCalculatedPremiumAZN],
    @StatusMessage AS [DecisionNote];

