-- 1. Sığorta hadisəsinin təsdiqlənməsi üçün Stored Procedure
CREATE OR ALTER PROCEDURE [dbo].[usp_ApproveInsuranceClaim]
    @ClaimID INT,
    @ApproverID INT,
    @ApprovedPayout DECIMAL(10, 2),
    @ResultStatus NVARCHAR(100) OUTPUT  -- Nəticəni kənara qaytaran parametr
AS
BEGIN
    -- Şəbəkəyə lazımsız "(1 row affected)" mesajlarının getməməsi üçün:
    SET NOCOUNT ON;

    -- 1. Biznes Qaydası Yoxlanışı: Məbləğ müsbət olmalıdır
    IF @ApprovedPayout <= 0
    BEGIN
        SET @ResultStatus = N'XƏTA: Ödəniş məbləği 0-dan böyük olmalıdır!';
        RETURN;
    END

    -- 2. Tranzaksiyanın başlanması (Hamısı icra olunmalı, ya da heç biri)
    BEGIN TRY
        BEGIN TRANSACTION;

        -- Addım A: Claims cədvəlində statusu yeniləyirik
        UPDATE [dbo].[InsuranceClaims]
        SET 
            [ClaimStatus] = N'APPROVED',
            [ApprovedBy] = @ApproverID,
            [ApprovedAmount] = @ApprovedPayout,
            [UpdatedAt] = SYSDATETIME()
        WHERE [ClaimID] = @ClaimID
          AND [ClaimStatus] = N'PENDING'; -- Yalnız gözləmədə olanlar təsdiqlənə bilər

        -- Əgər heç bir sətir yenilənmədisə (məs. Claim tapılmadı və ya artıq təsdiqlənib)
        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultStatus = N'XƏTA: Zərər müraciəti tapılmadı və ya artıq təsdiqlənib!';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        -- Addım B: Audit loq cədvəlinə qeyd yazırıq
        INSERT INTO [dbo].[ClaimAuditLogs] ([ClaimID], [ActionType], [PerformedBy], [ActionDate])
        VALUES (@ClaimID, N'CLAIM_APPROVED', @ApproverID, SYSDATETIME());

        -- Hər şey uğurludur: Dəyişiklikləri qalıcı edirik
        COMMIT TRANSACTION;
        SET @ResultStatus = N'UĞURLU: Zərər müraciəti təsdiqləndi və ödənişə yönəldildi.';
    END TRY
    BEGIN CATCH
        -- Gözlənilməz sistem xətası baş verərsə tranzaksiyanı geri alırıq
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ResultStatus = N'SİSTEM XƏTASI: ' + ERROR_MESSAGE();
    END CATCH
END;

