-- 1. Skalyar Funksiya: KASKO zərərlilik dərəcəsinə görə Risk Kateqoriyasını təyin edir
CREATE OR ALTER FUNCTION [dbo].[fn_GetRiskCategory] (
    @LossRatio DECIMAL(5, 2)
)
RETURNS NVARCHAR(30)
AS
BEGIN
    DECLARE @RiskCategory NVARCHAR(30);

    IF @LossRatio IS NULL OR @LossRatio = 0.00
        SET @RiskCategory = N'RİSKSİZ (İdeal)';
    ELSE IF @LossRatio < 50.00
        SET @RiskCategory = N'AŞAĞI RİSK (Gəlirli)';
    ELSE IF @LossRatio BETWEEN 50.00 AND 80.00
        SET @RiskCategory = N'ORTA RİSK (Qəbulolunan)';
    ELSE
        SET @RiskCategory = N'YÜKSƏK RİSK (Zərərli!)';

    RETURN @RiskCategory;
END;
GO

-- 2. Table-Valued Funksiya (iTVF): Müəyyən risk həddindən yuxarı olan filialları cədvəl kimi qaytarır
CREATE OR ALTER FUNCTION [dbo].[fn_GetHighRiskBranches] (
    @MinLossRatio DECIMAL(5, 2)
)
RETURNS TABLE
AS
RETURN (
    SELECT 
        [BranchName],
        [TotalPremiumAZN],
        [TotalPaidClaimsAZN],
        ROUND(([TotalPaidClaimsAZN] / NULLIF([TotalPremiumAZN], 0)) * 100.0, 2) AS [LossRatioPct]
    FROM [dbo].[BranchFinancials]
    WHERE ROUND(([TotalPaidClaimsAZN] / NULLIF([TotalPremiumAZN], 0)) * 100.0, 2) >= @MinLossRatio
);
GO

-- 3. Hər iki funksiyanın birlikdə tək bir hesabat sorğusunda istifadəsi:
SELECT 
    b.[BranchName],
    b.[TotalPremiumAZN],
    b.[TotalPaidClaimsAZN],
    b.[LossRatioPct],
    [dbo].[fn_GetRiskCategory](b.[LossRatioPct]) AS [RiskEvaluation]
FROM [dbo].[fn_GetHighRiskBranches](60.00) b
ORDER BY b.[LossRatioPct] DESC;

