FROM [dbo].[InsuranceClaims]
WHERE [ClaimID] = 101;

-- Ən vacib addım: Bazanı əvvəlki təmiz vəziyyətinə qaytarırıq!
ROLLBACK TRANSACTION;
PRINT N'Test tamamlandı. Bütün dəyişikliklər təhlükəsiz şəkildə geri alındı (Rollback).';

-- 2. Praktiki Analitik Sorğu: Hər filial üzrə ən son 1 sığorta hadisəsi
WITH LatestBranchClaims AS (
    SELECT 
        c.[ClaimID],
        c.[BranchName],
        c.[CustomerName],
        c.[ApprovedAmount],
        c.[IncidentDate],
        ROW_NUMBER() OVER (
            PARTITION BY c.[BranchName] 
            ORDER BY c.[IncidentDate] DESC
        ) AS [ClaimRank]
    FROM [dbo].[InsuranceClaims] c
    WHERE c.[IncidentDate] >= '2026-01-01' -- S-ARG-able indeks axtarışı
)
SELECT 
    [BranchName],
    [ClaimID],
    [CustomerName],
    [ApprovedAmount],
    [IncidentDate]
FROM LatestBranchClaims
WHERE [ClaimRank] = 1
ORDER BY [ApprovedAmount] DESC;

