def parse_batch_safely(raw_records):
    valid = []
    failed = []
    for row in raw_records:
        try:
            val = int(row['value'])
            valid.append({'id': row['id'], 'value': val})
        except (ValueError, TypeError) as e:
            failed.append({'id': row['id'], 'error': str(e)})
    return (valid, failed)

