import json
import time

# Simulated remote paginated API
def mock_api_call(page: int):
    if page > 3:
        return {"data": [], "has_more": False}
    return {
        "data": [{"event_id": f"evt_{(page - 1) * 2 + i}", "user_id": 100 + i} for i in range(1, 3)],
        "has_more": page < 3
    }

def ingest_all_records():
    all_records = []
    page = 1
    has_more = True
    max_retries = 3

    while has_more:
        for attempt in range(max_retries):
            try:
                response = mock_api_call(page)
                batch = response.get("data", [])
                all_records.extend(batch)
                has_more = response.get("has_more", False)
                page += 1
                break
            except Exception as err:
                if attempt == max_retries - 1:
                    raise RuntimeError(f"API failed after {max_retries} attempts: {err}")
                time.sleep(0.05 * (2 ** attempt))

    return all_records

results = ingest_all_records()
print(f"Successfully ingested {len(results)} events from external API.")
print("Sample event:", results[0])

