# Production Blueprint: Modern TaskFlow API Pipeline with Hybrid Operators
from datetime import datetime, timedelta
from airflow.decorators import dag, task
from airflow.operators.empty import EmptyOperator

default_args = {
    'owner': 'analytics_eng',
    'retries': 2,
    'retry_delay': timedelta(minutes=2)
}

@dag(
    dag_id='04_modern_taskflow_etl',
    default_args=default_args,
    start_date=datetime(2026, 1, 1),
    schedule='@daily',
    catchup=False,
    tags=['taskflow', 'modern', 'airflow2']
)
def taskflow_pipeline():

    start = EmptyOperator(task_id='start')
    end = EmptyOperator(task_id='end')

    @task
    def extract_orders() -> dict:
        """Extract order records and return metadata summary."""
        print("📥 Extracted 1,200 orders from transactional API.")
        return {"batch_id": "b_20261015", "order_count": 1200, "total_value": 84500.50}

    @task
    def validate_and_transform(metadata: dict) -> dict:
        """Cleanse records using extracted XCom metadata."""
        count = metadata["order_count"]
        print(f"⚙️ Transforming batch {metadata['batch_id']}. Found {count} orders.")
        return {"batch_id": metadata["batch_id"], "clean_count": count - 12, "currency": "AZN"}

    @task
    def load_lakehouse(clean_summary: dict):
        """Load final summary partition into warehouse."""
        print(f"🚀 Loaded {clean_summary['clean_count']} valid rows into Lakehouse. Batch closed.")

    # Natural Python invocation automatically builds XComs and dependencies!
    raw_meta = extract_orders()
    clean_meta = validate_and_transform(raw_meta)
    load_done = load_lakehouse(clean_meta)

    # Hybrid integration with classic EmptyOperators
    start >> raw_meta
    load_done >> end

# Instantiate the DAG
pipeline_instance = taskflow_pipeline()

