# Demonstrating Keyed Hashing vs Sticky Partitioning in Confluent Kafka
import json
from confluent_kafka import Producer

producer = Producer({'bootstrap.servers': 'localhost:9092'})

def callback(err, msg):
    if err:
        print(f"Error: {err}")
    else:
        key_str = msg.key().decode('utf-8') if msg.key() else 'NULL'
        print(f"  • Key: {key_str:<12} ──► Routed to Partition: {msg.partition()} [Offset: {msg.offset()}]")

print("=== 1. Producing Keyed Messages (Deterministic Routing) ===")
# Customer A events: ALWAYS map to the same partition
for i in range(3):
    payload = {"tx_id": f"tx_{i}", "customer": "cust_A", "amt": 50 * (i + 1)}
    producer.produce("orders-stream", key="cust_A", value=json.dumps(payload), callback=callback)

# Customer B events: ALWAYS map to another deterministic partition
for i in range(2):
    payload = {"tx_id": f"tx_{i}", "customer": "cust_B", "amt": 99.0}
    producer.produce("orders-stream", key="cust_B", value=json.dumps(payload), callback=callback)

print("\n=== 2. Producing Null-Key Messages (Sticky Batching) ===")
for i in range(3):
    payload = {"log_event": f"heartbeat_{i}"}
    producer.produce("orders-stream", key=None, value=json.dumps(payload), callback=callback)

producer.flush()

